// URLs of the images used by questions. Everything is bundled: flags come from
// the flag-icons package (processed by Vite), silhouettes and coats of arms
// from public/ (generated by the data pipeline).

import type { Media } from '../engine'

const flagUrls = import.meta.glob<string>('../../node_modules/flag-icons/flags/4x3/*.svg', {
  eager: true,
  query: '?url',
  import: 'default',
})

const flagByCode = new Map(
  Object.entries(flagUrls).map(([path, url]) => [path.slice(path.lastIndexOf('/') + 1, -4), url]),
)

export function mediaUrl(media: Media): string | undefined {
  switch (media.kind) {
    case 'flag':
      return flagByCode.get(media.key)
    case 'silhouette':
      return `${import.meta.env.BASE_URL}silhouettes/${media.key}.svg`
    case 'coat-of-arms':
      return `${import.meta.env.BASE_URL}coats-of-arms/${media.key}.webp`
  }
}
